s = s.replace(""" * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */""", """ * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 *
 * Calendar days are a different matter: every workspace runs on its own
 * clock (`OrganizationSettings.timeZone`, an IANA zone name), and every day
 * boundary — overdue, the digest window, the activity feed's days, the
 * retention cut-off — is taken on that clock. A calendar date is a plain
 * `YYYY-MM-DD` string; `localDate()` maps an instant onto one and
 * `startOfLocalDate()` maps one back onto the instant it began.
 */""")

s = s.replace("""const WEEK_MS = 7 * DAY_MS;
""", """const WEEK_MS = 7 * DAY_MS;

const CALENDAR_DATE = /^(\\d{4})-(\\d{2})-(\\d{2})$/;
""")

old_overdue = s[s.index("/** True when a due date exists and has already passed. */"):s.index("export function addDays")]
new_overdue = '''/**
 * True when a due date exists and the workspace's calendar day containing it
 * has ended. Due dates are whole days: on the due day itself an issue is not
 * overdue yet, whatever time of day `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return (
    parseIso(dueAt).getTime() <
    parseIso(startOfLocalDay(reference, timeZone)).getTime()
  );
}

'''
s = s.replace(old_overdue, new_overdue)

old_digest = s[s.index("/**\n * The 24-hour window a digest covers"):]
new_digest = '''/**
 * The window a digest covers, ending at the most recent local `digestHour:00`
 * at or before `reference`: today's if it has passed, yesterday's otherwise —
 * so a job run early never mails an empty digest and then skips the real
 * one. It starts at the same local hour on the previous calendar day, so
 * across a DST change it spans 23 or 25 hours rather than 24.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  const atDigestHour = (date: string): number =>
    instantOfWallTime(calendarDateMs(date) + digestHour * HOUR_MS, timeZone);

  let endDate = localDateOf(reference.getTime(), timeZone);
  let end = atDigestHour(endDate);
  if (end > reference.getTime()) {
    endDate = addCalendarDays(endDate, -1);
    end = atDigestHour(endDate);
  }

  return {
    start: toIsoTimestamp(new Date(atDigestHour(addCalendarDays(endDate, -1)))),
    end: toIsoTimestamp(new Date(end)),
  };
}

/** True when `Intl` recognises `timeZone` as a time zone name. */
export function isValidTimeZone(timeZone: string): boolean {
  if (typeof timeZone !== "string" || timeZone.length === 0) return false;
  try {
    zoneFormatter(timeZone);
    return true;
  } catch {
    return false;
  }
}

/** Refuses a zone name `Intl` does not recognise. */
export function assertValidTimeZone(timeZone: string): void {
  if (!isValidTimeZone(timeZone)) {
    throw new RangeError(`Unknown time zone: "${String(timeZone)}"`);
  }
}

/** The `YYYY-MM-DD` calendar date of `value` on the clock of `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return localDateOf(parseIso(value).getTime(), timeZone);
}

/**
 * The instant at which the calendar day containing `reference` began on the
 * clock of `timeZone` — local midnight, or the first instant after it where
 * a DST change skipped midnight.
 */
export function startOfLocalDay(
  reference: Date,
  timeZone: string,
): IsoTimestamp {
  return startOfLocalDate(localDateOf(reference.getTime(), timeZone), timeZone);
}

/** The instant at which calendar date `date` (`YYYY-MM-DD`) began in `timeZone`. */
export function startOfLocalDate(date: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(firstInstantOf(date, timeZone)));
}

/** Calendar arithmetic on a `YYYY-MM-DD` date; DST plays no part in it. */
export function addCalendarDays(date: string, days: number): string {
  return new Date(calendarDateMs(date) + days * DAY_MS)
    .toISOString()
    .slice(0, 10);
}

// ---------------------------------------------------------------------------
// Zone arithmetic. A "wall time" is a local clock reading encoded as if it
// were a UTC epoch value, which makes calendar maths on it plain arithmetic.

const zoneFormatters = new Map<string, Intl.DateTimeFormat>();

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
function zoneFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = zoneFormatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    zoneFormatters.set(timeZone, formatter);
  }
  return formatter;
}

/** What the clock of `timeZone` reads at `instantMs`, as a wall time. */
function wallTimeAt(instantMs: number, timeZone: string): number {
  const fields = { year: 0, month: 1, day: 1, hour: 0, minute: 0, second: 0 };
  for (const part of zoneFormatter(timeZone).formatToParts(instantMs)) {
    if (part.type in fields) {
      fields[part.type as keyof typeof fields] = Number(part.value);
    }
  }
  const wall = new Date(0);
  wall.setUTCFullYear(fields.year, fields.month - 1, fields.day);
  wall.setUTCHours(fields.hour, fields.minute, fields.second, 0);
  return wall.getTime() + (((instantMs % 1000) + 1000) % 1000);
}

function localDateOf(instantMs: number, timeZone: string): string {
  return new Date(wallTimeAt(instantMs, timeZone)).toISOString().slice(0, 10);
}

/**
 * The instant at which the clock of `timeZone` reads `wall`. A reading that
 * happens twice (clocks went back) resolves to the earlier instant; one that
 * never happens (clocks sprang forward) is pushed forward by the gap, e.g.
 * 02:30 on a spring-forward night becomes 03:30.
