/**
 * The workspace clock: `settings.timeZone` is stored, read back and validated.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import { updateOrganization } from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("organization time zone", () => {
  it("defaults a new workspace to UTC", async () => {
    const tenant = await createTenant("tz-default");

    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
  });

  it("stores the zone with the other settings", async () => {
    const tenant = await createTenant("tz-update");

    const updated = await updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });

    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect(updated.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");

    // A later patch that does not mention the zone keeps it.
    const later = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 9 },
    });
    expect(later.settings.timeZone).toBe("Asia/Tokyo");
    expect(later.settings.digestHourUtc).toBe(9);
  });

  it("refuses a zone Intl does not recognise and changes nothing", async () => {
    const tenant = await createTenant("tz-invalid");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Europe/Paris" },
    });

    await expect(
      updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "Renamed inc",
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 3 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    await expect(
      orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        settings: { timeZone: "Not/AZone" },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.name).toBe(tenant.org.name);
    expect(stored?.settings.timeZone).toBe("Europe/Paris");
    expect(stored?.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
  });

  it("validates the zone in the settings schema", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
    expect(organizationSettingsSchema.parse({ timeZone: "Asia/Tokyo" }).timeZone).toBe(
      "Asia/Tokyo",
    );
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(
      false,
    );

    const patch = updateOrganizationSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      settings: { digestHourUtc: 9 },
    });
    expect(patch.settings?.timeZone).toBeUndefined();
  });
});
EOF
cat > tests/jobs/cleanup-archived-job.test.ts <<'EOF'
/**
 * The retention cut-off is local midnight `retentionDays` calendar days back
 * on the workspace clock, not `retentionDays × 24h` before now.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

let cleanup: () => void;
const orgIds: Record<string, OrgId> = {};

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();

  for (const [slug, timeZone] of [
    ["retain-utc", "UTC"],
    ["retain-tokyo", "Asia/Tokyo"],
    ["retain-new-york", "America/New_York"],
  ] as const) {
    const tenant = await createTenant(slug, "free");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone } });
    await usageRepo.recomputeUsage(tenant.org.id);
    orgIds[slug] = tenant.org.id;
  }
});

afterEach(() => {
  vi.restoreAllMocks();
});

afterAll(() => {
  cleanup();
});

async function cutoffsAt(now: Date): Promise<Record<string, string>> {
  const purge = vi.spyOn(activityRepo, "purgeActivityBefore").mockResolvedValue(0);
  await runCleanupArchivedJob(now);

  const byOrg: Record<string, string> = {};
  for (const [orgId, cutoff] of purge.mock.calls) byOrg[orgId] = cutoff;
  return byOrg;
}

describe("jobs/cleanup-archived-job", () => {
  it("cuts off at local midnight retentionDays calendar days ago", async () => {
    expect(getPlanLimits("free").retentionDays).toBe(30);

    const cutoffs = await cutoffsAt(new Date("2026-06-01T07:00:00.000Z"));

    // Today is 1 June in UTC and in Tokyo (16:00), still 31 May in New York (03:00).
    expect(cutoffs[orgIds["retain-utc"]!]).toBe("2026-05-02T00:00:00.000Z");
    expect(cutoffs[orgIds["retain-tokyo"]!]).toBe("2026-05-01T15:00:00.000Z");
    expect(cutoffs[orgIds["retain-new-york"]!]).toBe("2026-05-01T04:00:00.000Z");
  });

  it("counts calendar days across a DST change", async () => {
    // 30 days before 10 March (EDT) is 8 February, whose midnight is EST.
    const cutoffs = await cutoffsAt(new Date("2026-03-10T12:00:00.000Z"));

    expect(cutoffs[orgIds["retain-new-york"]!]).toBe("2026-02-08T05:00:00.000Z");
  });
});
EOF
